import * as THREE from 'three/webgpu';
import { color, mix, smoothstep, texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const primitiveResults = [];
  let cleaned = false;

  root.userData.handlers = {};

  const visualSpec = config.intent?.visualSpec ?? {};
  const specColors = visualSpec.colors ?? {};
  const ink = specColors.ink ?? '#16161d';
  const paper = specColors.paper ?? '#e8ecf2';
  const accent = specColors.accent ?? '#ff2a38';
  const surface = specColors.surface ?? '#0b0b10';

  const region = config.atlasRegion ?? {
    x: 0,
    y: 0,
    width: 512,
    height: 320
  };

  const aspect = region.width / region.height;
  const cardHeight = 1.18;
  const cardWidth = cardHeight * aspect;

  const makeBillboard = (object) => {
    object.onBeforeRender = (_renderer, _scene, camera) => {
      if (!cleaned && camera) object.quaternion.copy(camera.quaternion);
    };
    return object;
  };

  const gradientMaterial = new THREE.MeshBasicNodeMaterial({
    side: THREE.DoubleSide
  });
  const gradientT = smoothstep(0.0, 1.0, uv().y);
  gradientMaterial.colorNode = mix(
    color(ink),
    mix(color(surface), color(ink), gradientT),
    smoothstep(0.12, 0.88, uv().y)
  );

  const stageGeometry = new THREE.PlaneGeometry(cardWidth + 0.18, cardHeight + 0.18);
  const stage = makeBillboard(new Mesh(stageGeometry, gradientMaterial));
  stage.position.z = -0.08;
  root.add(stage);
  resources.push(stageGeometry, gradientMaterial);

  const shadowMaterial = new THREE.MeshBasicNodeMaterial({
    color: new THREE.Color('#000000'),
    transparent: true,
    opacity: 0.46,
    depthWrite: false,
    side: THREE.DoubleSide
  });
  const shadowGeometry = new THREE.PlaneGeometry(cardWidth + 0.28, cardHeight + 0.22);
  const shadow = makeBillboard(new Mesh(shadowGeometry, shadowMaterial));
  shadow.position.set(0.045, -0.055, -0.11);
  root.add(shadow);
  resources.push(shadowGeometry, shadowMaterial);

  const imageMaterial = new THREE.MeshBasicNodeMaterial({
    color: new THREE.Color(paper),
    side: THREE.DoubleSide
  });
  const imageGeometry = new THREE.PlaneGeometry(cardWidth, cardHeight);
  const image = makeBillboard(new Mesh(imageGeometry, imageMaterial));
  image.position.z = 0;
  root.add(image);
  resources.push(imageGeometry, imageMaterial);

  const accentMaterial = new THREE.MeshBasicNodeMaterial({
    color: new THREE.Color(accent),
    side: THREE.DoubleSide
  });
  const accentGeometry = new THREE.PlaneGeometry(0.026, cardHeight * 0.72);
  const accentRail = makeBillboard(new Mesh(accentGeometry, accentMaterial));
  accentRail.position.set(cardWidth * 0.5 + 0.045, 0, 0.035);
  root.add(accentRail);
  resources.push(accentGeometry, accentMaterial);

  const topRuleGeometry = new THREE.PlaneGeometry(cardWidth * 0.34, 0.018);
  const topRule = makeBillboard(new Mesh(topRuleGeometry, accentMaterial));
  topRule.position.set(-cardWidth * 0.22, cardHeight * 0.5 + 0.045, 0.035);
  root.add(topRule);
  resources.push(topRuleGeometry);

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((loadedTexture) => {
      if (cleaned || !loadedTexture) return;

      const imageWidth = loadedTexture.image?.width ?? region.width;
      const imageHeight = loadedTexture.image?.height ?? region.height;

      loadedTexture.wrapS = THREE.ClampToEdgeWrapping;
      loadedTexture.wrapT = THREE.ClampToEdgeWrapping;
      loadedTexture.repeat.set(
        region.width / imageWidth,
        region.height / imageHeight
      );
      loadedTexture.offset.set(
        region.x / imageWidth,
        1 - ((region.y + region.height) / imageHeight)
      );
      loadedTexture.colorSpace = THREE.SRGBColorSpace;
      loadedTexture.needsUpdate = true;

      imageMaterial.map = texture(loadedTexture);
      imageMaterial.needsUpdate = true;
      resources.push(loadedTexture);
    }).catch(() => {});
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler !== 'function') continue;

    const result = handler(root, primitive.params);
    if (result) primitiveResults.push(result);
  }

  root.userData.cleanup = () => {
    if (cleaned) return;
    cleaned = true;

    for (const result of primitiveResults) {
      if (typeof result.cleanup === 'function') result.cleanup();
      if (result.timeline?.kill) result.timeline.kill();
    }

    root.traverse((object) => {
      object.onBeforeRender = null;
    });

    const disposed = new Set();
    for (const resource of resources) {
      if (!resource || disposed.has(resource)) continue;
      disposed.add(resource);
      if (typeof resource.dispose === 'function') resource.dispose();
    }

    root.clear();
  };

  return root;
}
